// ws 延迟加载：通过 optionalRequire 运行时按需加载，模块名以片段拼接，
// 使打包器（webpack/Next.js）静态分析阶段无法识别，从而不会报 Module not found。
let _WS: any = null
// 是否已尝试过加载 ws。未安装时 _WS 恒为 null，用此标记避免每次读取
// adapter.wsClass（getter）都重复执行 optionalRequire 并重复打印安装提示。
let _wsTried = false
function getWS() {
  if (!_WS && !_wsTried) {
    _wsTried = true
    _WS = optionalRequire(['w', 's'], '缺少依赖 ws，请执行以下命令安装：\n\n'
      + '  npm install ws\n\n'
      + '该依赖用于 Node 环境下的 WebSocket 连接。')
  }
  return _WS
}

