/**
 * Logger 实现（v3 风格）。
 *
 * v3.x node-sdk 提供 `app.logger()` 返回 Log 实例，支持 log/info/error/warn 四个级别。
 * 在云函数 SCF 环境且开通 CLS 日志服务时，转发到 `console.__baseLog__`；
 * 其他环境退化到 `console[level]`。
 *
 * v4 js-sdk 默认不提供 logger。这里在 node adapter 里挂载一个兼容实现，
 * 让依赖 `app.logger()` 的下游（如 wx-server-sdk）可以继续工作。
 */

import { getCloudbaseContext } from './context'

export type LogLevel = 'log' | 'info' | 'error' | 'warn'

export class Log {
  private isSupportClsReport: boolean

  public constructor() {
    const { _SCF_TCB_LOG } = getCloudbaseContext()
    this.isSupportClsReport = true
    if (`${_SCF_TCB_LOG}` !== '1') {
      this.isSupportClsReport = false
    } else if (!(console as any).__baseLog__) {
      this.isSupportClsReport = false
    }

    if (!this.isSupportClsReport) {
      // 当前非 tcb scf 环境 或 未开通 CLS，log 功能退化为 console
      // 不打印 warn，避免污染业务日志
    }
  }

  /**
   * 目前 logMsg 只支持 object 形式（与 v3 一致）
   */
  public transformMsg(logMsg: any): Record<string, any> {
    let realMsg: Record<string, any> = {}
    if (logMsg && typeof logMsg === 'object' && !Array.isArray(logMsg)) {
      realMsg = { ...realMsg, ...logMsg }
    } else {
      realMsg = { msg: logMsg }
    }
    return realMsg
  }

  public baseLog(logMsg: any, logLevel: LogLevel) {
    if (Object.prototype.toString.call(logMsg).slice(8, -1) !== 'Object') {
      // 与 v3 行为一致：非 object 抛错
      // 但为了兼容下游可能传 string，包装一层
      logMsg = { msg: logMsg }
    }

    const msgContent = this.transformMsg(logMsg)

    if (this.isSupportClsReport) {
      (console as any).__baseLog__(msgContent, logLevel)
    } else {
      const fn = (console as any)[logLevel]
      if (typeof fn === 'function') {
        fn(msgContent)
      } else {
        console.log(msgContent)
      }
    }
  }

  public log(logMsg: any) {
    this.baseLog(logMsg, 'log')
  }

  public info(logMsg: any) {
    this.baseLog(logMsg, 'info')
  }

  public error(logMsg: any) {
    this.baseLog(logMsg, 'error')
  }

  public warn(logMsg: any) {
    this.baseLog(logMsg, 'warn')
  }
}

let loggerInstance: Log | null = null

/**
 * 获取/创建 Logger 实例。
 * 与 v3 node-sdk 的 `logger()` 行为一致，单例缓存。
 */
export function logger(): Log {
  if (!loggerInstance) {
    loggerInstance = new Log()
  }
  return loggerInstance
}
