/**
 * 可选依赖的“打包器无感”按需加载工具。
 *
 * 背景：
 *   Node 端能力用到几个可选依赖（jsonwebtoken / @cloudbase/signature-nodejs / ws），
 *   它们只应在 Node 服务端、且仅当真正调用相关能力时才加载。为此我们做了运行时按需加载。
 *
 * 但仅仅“运行时 require / 动态 import”并不够：
 *   webpack / Next.js 等打包器在**静态分析**阶段，只要看到 `require("字面量")`
 *   或 `import("字面量")` 中的字符串字面量，就会尝试去 resolve 这个模块，
 *   未安装即报 `Module not found`。这会波及使用方的浏览器 / SSR 构建。
 *
 * 根治思路（本文件的核心）：
 *   让打包器在静态分析时**看不到**模块名字面量，从而彻底不去 resolve：
 *   1) 模块名在运行时由片段拼接得到（非字面量），阻止常量折叠；
 *   2) require 从宿主运行时获取：CJS 用 direct eval('require') 取模块级真实 require
 *      （既能拿到模块包装器注入的局部 require，又不会被打包器改写为自身加载器），
 *      ESM 用 process.getBuiltinModule('module').createRequire 构造；
 *   3) 仅在 Node 运行时（存在 process.versions.node）才尝试加载，
 *      其它环境直接返回 null。
 *
 * 结果：使用方无论浏览器还是 SSR 打包都不会再出现 `Module not found`，
 *      且无需在 next.config.js 等处做任何额外配置；仅当在 Node 端真正调用到
 *      相关能力、且未安装依赖时，才会在运行时给出“请安装 xxx”的提示。
 */

/** 是否处于 Node.js 运行时 */
function isNodeRuntime(): boolean {
  return (
    typeof process !== 'undefined'
    && !!(process as any).versions
    && (process as any).versions.node != null
  )
}

/**
 * 获取宿主运行时的真实 require（CJS 或 ESM 均可用），且对打包器不可见。
 *
 * - direct eval('require')：在当前词法作用域内执行，能拿到 CJS 模块包装器注入的
 *   真实 require；且 eval 内字符串对 webpack 不可见，不会被替换成 __webpack_require__，
 *   其参数也不会被纳入静态依赖分析。
 * - 若上述方式拿不到（ESM 环境无 require），退回到 process.getBuiltinModule 的 createRequire。
 */
function getRuntimeRequire(): ((id: string) => any) | null {
  // 路径 1（CJS 产物 / 关键）：用 “直接 eval(direct eval)” 拿宿主运行时的真实 require。
  //   为什么必须用 eval 而不是源码里直接写 require：
  //   - 源码里裸写的 `require` 会被 webpack/Next.js 改写为 __webpack_require__，
  //     从而 require('jsonwebtoken') 找的是打包 chunk 而非真实模块，导致拿不到；
  //   - `new Function('return require')` 强制在“全局作用域”执行，而 CJS 的 require
  //     是模块包装器注入的“局部变量”，全局作用域看不到 → 得到 undefined（此前返回 null 的根因）。
  //   direct eval 的特性正好两全：它在“当前词法作用域”内执行，能拿到模块级注入的 require；
  //   同时 eval 内的字符串对打包器完全不可见，require 不会被改写、其参数也不进静态依赖分析。
  try {
    // eslint-disable-next-line no-eval
    const req = eval('typeof require !== "undefined" ? require : null')
    if (typeof req === 'function') {
      return req as (id: string) => any
    }
  } catch (_e) {
    /* ignore，尝试下一种方式 */
  }

  // 路径 2（ESM 产物）：ESM 下没有 require，需用 module.createRequire 构造。
  //   optionalRequire 是同步 API，不能 await import('module')，因此用 Node 提供的
  //   同步方式 process.getBuiltinModule('module')（Node 20.16+）拿到内置 module。
  try {
    // 模块名用片段拼接，避免被打包器识别为静态依赖
    const builtinModuleName = ['mod', 'ule'].join('')

    const proc = typeof process !== 'undefined' ? (process as any) : null
    const getBuiltin = proc && typeof proc.getBuiltinModule === 'function'
      ? proc.getBuiltinModule.bind(proc)
      : null

    const mod = getBuiltin ? getBuiltin(builtinModuleName) : null

    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    if (mod && typeof mod.createRequire === 'function') {
      // 解析基准：优先用 ESM 的 import.meta.url（用 eval 绕过 CJS 语法限制与打包器静态分析），
      //   取不到时退回当前工作目录，以便解析使用方 node_modules 中的可选依赖。
      let base: string
      try {
        // eslint-disable-next-line no-eval
        const metaUrl = eval('typeof import.meta !== "undefined" ? import.meta.url : ""')
        base = metaUrl || `${process.cwd()}/`
      } catch (_err) {
        base = `${process.cwd()}/`
      }
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      return mod.createRequire(base) as (id: string) => any
    }
  } catch (_e) {
    /* ignore */
  }

  return null
}

/**
 * 按需加载一个可选依赖。
 *
 * @param moduleNameParts 模块名的片段数组，运行时 join 得到真实名字（阻止打包器识别字面量）。
 *   例如 jsonwebtoken 传 ['json', 'webtoken']；@cloudbase/signature-nodejs 传
 *   ['@cloudbase', '/', 'signature-nodejs']。
 * @param installHint 缺失依赖时打印的安装提示。
 * @returns 模块导出对象；非 Node 环境或未安装时返回 null。
 */
export function optionalRequire<T = any>(
  moduleNameParts: string[],
  installHint?: string,
): T | null {
  if (!isNodeRuntime()) {
    return null
  }

  // 运行时拼接模块名 —— 关键：这里不能是字符串字面量
  const moduleName = moduleNameParts.join('')

  const req = getRuntimeRequire()

  if (!req) {
    return null
  }

  try {
    return req(moduleName) as T
  } catch (_e) {
    if (installHint) {
      console.error(installHint)
    }
    return null
  }
}
